                            int width, int height, int maxIterations,
                            int output[]) {
    const float dx = (x1 - x0) / width;
    const float dy = (y1 - y0) / height;
    const int lane_count = 8;

    for (int j = 0; j < height; ++j) {
        const float y = y0 + j * dy;

        for (int block = 0; block < width; ) {
            int valid = width - block;
            if (valid > lane_count)
                valid = lane_count;

            float c_re[8];
            float z_re[8];
            float z_im[8];
            int iterations[8];
            int active[8];

            #pragma omp simd
            for (int lane = 0; lane < lane_count; ++lane) {
                if (lane < valid) {
                    const int pixel = block + lane;
                    const float x = x0 + pixel * dx;
                    c_re[lane] = x;
                    z_re[lane] = x;
                    z_im[lane] = y;
                    iterations[lane] = 0;
                    active[lane] = 1;
                } else {
                    c_re[lane] = 0.0f;
                    z_re[lane] = 0.0f;
                    z_im[lane] = 0.0f;
                    iterations[lane] = 0;
                    active[lane] = 0;
                }
            }

            for (int iteration = 0; iteration < maxIterations; ++iteration) {
                int any_active = 0;
                #pragma omp simd reduction(|:any_active)
                for (int lane = 0; lane < lane_count; ++lane) {
                    const float norm = z_re[lane] * z_re[lane] +
                                       z_im[lane] * z_im[lane];
                    const int keep = active[lane] & !(norm > 4.0f);
                    const float new_re = z_re[lane] * z_re[lane] -
                                         z_im[lane] * z_im[lane];
                    const float new_im = 2.0f * z_re[lane] * z_im[lane];

                    z_re[lane] = keep ? c_re[lane] + new_re : 0.0f;
                    z_im[lane] = keep ? y + new_im : 0.0f;
                    iterations[lane] += keep;
                    active[lane] = keep;
                    any_active |= keep;
                }
                if (!any_active)
                    break;
            }

            #pragma omp simd
            for (int lane = 0; lane < valid; ++lane) {
                const int pixel = block + lane;
                output[j * width + pixel] = iterations[lane];
            }

            block += valid;
        }
    }
}

