                            ++iterations[lane];
                        }
                    }
                    any_active |= active[lane];
                }
                if (!any_active)
                    break;
            }

            #pragma omp simd
            for (int lane = 0; lane < valid; ++lane) {
                const int pixel = block + lane;
                output[j * width + pixel] = iterations[lane];
