    float dx = (x1 - x0) / width;
    float dy = (y1 - y0) / height;

    #pragma omp parallel for collapse(2) schedule(dynamic, 256) num_threads(threads)
    for (int j = 0; j < height; ++j) {
        for (int i = 0; i < width; ++i) {
            float x = x0 + i * dx;
            float y = y0 + j * dy;

            int index = (j * width + i);
            output[index] = mandel(x, y, maxIterations);
        }
    }
